#include <map>
#include <set>
#include <string>
#include <vector>

struct ObjectFile
{
    std::string name;
    std::vector<std::string> defines;
    std::vector<std::string> needs;
};

std::vector<std::string> linkErrors(const std::vector<ObjectFile>& objects)
{
    std::map<std::string, int> definedCount;      // std::map keeps symbols sorted
    std::set<std::string> needed;
    for (const ObjectFile& obj : objects)
    {
        for (const std::string& s : obj.defines) ++definedCount[s];
        for (const std::string& s : obj.needs) needed.insert(s);
    }

    std::vector<std::string> errors;
    for (const auto& [symbol, count] : definedCount)
        if (count > 1) errors.push_back("duplicate " + symbol);
    for (const std::string& symbol : needed)
        if (definedCount.find(symbol) == definedCount.end()) errors.push_back("unresolved " + symbol);
    return errors;
}

unitTests:
using Errors = std::vector<std::string>;
const ObjectFile mainObj{ "main.obj", { "main" }, { "addBonus", "printf" } };
const ObjectFile scoreObj{ "score.obj", { "addBonus" }, {} };
const ObjectFile crt{ "crt.lib", { "printf", "malloc" }, {} };
TEST("everything links") { CHECK(linkErrors({ mainObj, scoreObj, crt }).empty()); }
TEST("a missing file") { CHECK(linkErrors({ mainObj, crt }) == Errors{ "unresolved addBonus" }); }
TEST("defined twice") { CHECK(linkErrors({ mainObj, scoreObj, scoreObj, crt }) == Errors{ "duplicate addBonus" }); }
TEST("several of each, sorted, duplicates first")
{
    const ObjectFile a{ "a.obj", { "zeta", "alpha" }, { "missingB", "missingA" } };
    const ObjectFile b{ "b.obj", { "alpha", "zeta" }, { "missingA" } };
    CHECK(linkErrors({ a, b }) == Errors({ "duplicate alpha", "duplicate zeta", "unresolved missingA", "unresolved missingB" }));
}
TEST("using your own definition is fine") { CHECK(linkErrors({ ObjectFile{ "x.obj", { "helper" }, { "helper" } } }).empty()); }
TEST("nothing at all") { CHECK(linkErrors({}).empty()); }

